    83	            {error}
    84	          </p>
    85	        ) : null}
    86	        <div className="mt-6 flex flex-col gap-3 sm:flex-row">
    87	          <Button
    88	            aria-busy={isPending}
    89	            className="text-sm transition-none"
    90	            disabled={isPending}
    91	            onClick={() => void submitConsent(true)}
    92	            type="button"
    93	            variant="primary"
    94	          >
    95	            Allow access
    96	          </Button>
    97	          <Button
