   112	function readClaimNames(value: string | undefined) {
   113	  if (!value) return [];
   114	  try {
   115	    const parsed = JSON.parse(value) as Record<string, unknown>;
   116	    return Object.entries(parsed).flatMap(([target, targetClaims]) =>
   117	      targetClaims && typeof targetClaims === "object"
   118	        ? Object.keys(targetClaims).map((claim) => `${target}.${claim}`)
   119	        : [],
   120	    );
   121	  } catch {
   122	    return [];
   123	  }
