   135	async function readHumanClaims(
   136	  database: AppDb,
   137	  applicationId: string,
   138	  userId: string | null | undefined,
   139	): Promise<PrincipalClaims> {
   140	  if (!userId) throwOAuthError("invalid_grant", "A human principal is required.");
   141	
   142	  const principal = await database
   143	    .select({
   144	      principalId: humanPrincipals.principalId,
   145	      principalStatus: principals.status,
   146	      humanStatus: humanPrincipals.status,
   147	      disabled: humanPrincipals.disabled,
   148	    })
   149	    .from(humanPrincipals)
   150	    .innerJoin(principals, eq(principals.id, humanPrincipals.principalId))
   151	    .where(
   152	      and(
   153	        eq(humanPrincipals.userId, userId),
   154	        eq(principals.type, "human"),
   155	        eq(principals.status, "active"),
   156	        eq(humanPrincipals.status, "active"),
   157	        eq(humanPrincipals.disabled, false),
   158	      ),
   159	    )
   160	    .get();
   161	  if (!principal || principal.principalStatus !== "active" || principal.humanStatus !== "active") {
   162	    throwOAuthError("invalid_grant", "The human principal is disabled.");
   163	  }
   164	
   165	  const [directAssignment, memberships, directRoles] = await Promise.all([
   166	    database
   167	      .select({ id: userApplicationAssignments.id })
   168	      .from(userApplicationAssignments)
   169	      .where(
   170	        and(
   171	          eq(userApplicationAssignments.applicationId, applicationId),
   172	          eq(userApplicationAssignments.userPrincipalId, principal.principalId),
   173	          eq(userApplicationAssignments.status, "active"),
   174	        ),
   175	      )
   176	      .get(),
   177	    database
   178	      .select({ teamId: teamMemberships.teamId })
   179	      .from(teamMemberships)
   180	      .innerJoin(teams, eq(teams.id, teamMemberships.teamId))
   181	      .where(
   182	        and(eq(teamMemberships.userPrincipalId, principal.principalId), eq(teams.status, "active")),
   183	      )
   184	      .all(),
   185	    database
   186	      .select({ roleKey: applicationRoles.key })
   187	      .from(userApplicationRoleGrants)
   188	      .innerJoin(applicationRoles, eq(applicationRoles.id, userApplicationRoleGrants.roleId))
   189	      .where(
   190	        and(
   191	          eq(userApplicationRoleGrants.applicationId, applicationId),
   192	          eq(userApplicationRoleGrants.userPrincipalId, principal.principalId),
   193	          eq(applicationRoles.applicationId, applicationId),
   194	          eq(applicationRoles.status, "active"),
   195	        ),
   196	      )
   197	      .all(),
   198	  ]);
   199	
   200	  const teamIds = memberships.map((membership) => membership.teamId);
   201	  const [teamAssignments, teamRoles] = await Promise.all([
   202	    teamIds.length
   203	      ? database
   204	          .select({ teamId: teamApplicationAssignments.teamId })
   205	          .from(teamApplicationAssignments)
   206	          .where(
   207	            and(
   208	              eq(teamApplicationAssignments.applicationId, applicationId),
   209	              eq(teamApplicationAssignments.status, "active"),
   210	              inArray(teamApplicationAssignments.teamId, teamIds),
   211	            ),
   212	          )
   213	          .all()
   214	      : Promise.resolve([]),
   215	    teamIds.length
   216	      ? database
   217	          .select({ teamId: teamApplicationRoleGrants.teamId, roleKey: applicationRoles.key })
   218	          .from(teamApplicationRoleGrants)
   219	          .innerJoin(applicationRoles, eq(applicationRoles.id, teamApplicationRoleGrants.roleId))
   220	          .where(
   221	            and(
   222	              eq(teamApplicationRoleGrants.applicationId, applicationId),
   223	              eq(applicationRoles.applicationId, applicationId),
   224	              eq(applicationRoles.status, "active"),
   225	              inArray(teamApplicationRoleGrants.teamId, teamIds),
   226	            ),
   227	          )
   228	          .all()
   229	      : Promise.resolve([]),
   230	  ]);
   231	
   232	  if (!directAssignment && teamAssignments.length === 0) {
   233	    throwOAuthError("invalid_grant", "The principal is not assigned to this Application.");
   234	  }
   235	
   236	  const roles = Array.from(
   237	    new Set([...directRoles.map((role) => role.roleKey), ...teamRoles.map((role) => role.roleKey)]),
   238	  ).sort();
   239	  const relevantTeamIds = new Set([
   240	    ...teamAssignments.map((assignment) => assignment.teamId),
   241	    ...teamRoles.map((role) => role.teamId),
   242	  ]);
   243	
   244	  return {
   245	    principalId: principal.principalId,
   246	    principalType: "user",
   247	    roles,
   248	    teams: Array.from(relevantTeamIds).sort(),
   249	  };
   250	}
