   252	async function readServiceAccountClaims(
   253	  database: AppDb,
   254	  applicationId: string,
   255	  serviceAccountPrincipalId: string,
   256	): Promise<PrincipalClaims> {
   257	  const principal = await database
   258	    .select({
   259	      principalId: principals.id,
   260	      principalType: principals.type,
   261	      principalStatus: principals.status,
