   263	    .from(principals)
   264	    .innerJoin(serviceAccounts, eq(serviceAccounts.principalId, principals.id))
   265	    .where(and(eq(principals.id, serviceAccountPrincipalId), eq(principals.type, "service")))
   266	    .get();
   267	  if (!principal || principal.principalType !== "service") {
   268	    throwOAuthError("invalid_client", "The Service Account does not exist.");
   269	  }
   270	  if (principal.principalStatus !== "active") {
   271	    throwOAuthError("invalid_client", "The Service Account is disabled.");
   272	  }
   273	
   274	  const assignment = await database
   275	    .select({ id: serviceAccountApplicationAssignments.id })
   276	    .from(serviceAccountApplicationAssignments)
   277	    .where(
   278	      and(
   279	        eq(serviceAccountApplicationAssignments.applicationId, applicationId),
   280	        eq(
   281	          serviceAccountApplicationAssignments.serviceAccountPrincipalId,
   282	          serviceAccountPrincipalId,
   283	        ),
   284	        eq(serviceAccountApplicationAssignments.status, "active"),
   285	      ),
   286	    )
   287	    .get();
   288	  if (!assignment) {
   289	    throwOAuthError("invalid_grant", "The Service Account is not assigned to this Application.");
   290	  }
   291	
   292	  const roles = await database
   293	    .select({ roleKey: applicationRoles.key })
   294	    .from(serviceAccountApplicationRoleGrants)
   295	    .innerJoin(
   296	      applicationRoles,
   297	      eq(applicationRoles.id, serviceAccountApplicationRoleGrants.roleId),
   298	    )
   299	    .where(
   300	      and(
   301	        eq(serviceAccountApplicationRoleGrants.applicationId, applicationId),
   302	        eq(
   303	          serviceAccountApplicationRoleGrants.serviceAccountPrincipalId,
   304	          serviceAccountPrincipalId,
   305	        ),
   306	        eq(applicationRoles.applicationId, applicationId),
   307	        eq(applicationRoles.status, "active"),
   308	      ),
   309	    )
   310	    .orderBy(asc(applicationRoles.key))
   311	    .all();
   312	
   313	  return {
   314	    principalId: serviceAccountPrincipalId,
   315	    principalType: "service-account",
   316	    roles: Array.from(new Set(roles.map((role) => role.roleKey))).sort(),
   317	    teams: [],
