   321	export async function resolveShuiClaims(
   322	  environment: Pick<AuthEnvironment, "BETTER_AUTH_URL" | "DB">,
   323	  input: ClaimInput,
   324	) {
   325	  const database = createDb(environment.DB);
   326	  const managedClient = await readManagedClient(database, input.clientId);
   327	  if (!managedClient) return {};
   328	
   329	  assertTargetResource(
   330	    input.resources,
   331	    managedClient.resourceIdentifier,
   332	    input.requireTargetResource,
   333	  );
   334	  if (managedClient.status !== "active") {
   335	    throwOAuthError("invalid_target", "The Application is disabled.");
   336	  }
   337	
   338	  const principal =
   339	    managedClient.kind === "human"
   340	      ? await readHumanClaims(database, managedClient.applicationId, input.userId)
   341	      : await readServiceAccountClaims(
   342	          database,
   343	          managedClient.applicationId,
   344	          managedClient.serviceAccountPrincipalId ?? "",
   345	        );
   346	  const namespace = getShuiClaimNamespace(environment);
   347	  return {
   348	    [`${namespace}application_id`]: managedClient.applicationId,
   349	    [`${namespace}principal_id`]: principal.principalId,
   350	    [`${namespace}principal_type`]: principal.principalType,
   351	    [`${namespace}roles`]: principal.roles,
   352	    [`${namespace}teams`]: principal.teams,
   353	    [`${namespace}authz_version`]: managedClient.authzVersion,
   354	  };
   355	}
