     8	
     9	  return new Elysia({ aot: false, prefix: "/api" })
    10	    .onRequest(async ({ request }) => requireApiResource(request))
    11	    .use(createApiRoutes(environment, auth))
    12	    .get("/health", () => ({ service: "shui-api", status: "ok" as const }), {
    13	      response: t.Object({
    14	        service: t.String(),
    15	        status: t.Literal("ok"),
    16	      }),
    17	    })
    18	    .head("/health", () => new Response(null, { status: 204 }))
    19	    .mount(async (request) => {
    20	      const isPasswordReset =
    21	        request.method === "POST" &&
    22	        new URL(request.url).pathname.endsWith("/auth/request-password-reset");
    23	      const startedAt = Date.now();
    24	      const response = await auth.handler(request);
    25	      if (isPasswordReset) {
    26	        const remaining = PASSWORD_RESET_TIMING_FLOOR_MS - (Date.now() - startedAt);
    27	        if (remaining > 0) await new Promise((resolve) => setTimeout(resolve, remaining));
    28	      }
    29	      return response;
    30	    });
    31	}
