    35	async function requireApiResource(request: Request) {
    36	  const url = new URL(request.url);
    37	  const isAuthorize = url.pathname.endsWith("/oauth2/authorize");
    38	  const isToken = url.pathname.endsWith("/oauth2/token");
    39	  if (!isAuthorize && !isToken) return;
    40	
    41	  if (isAuthorize) {
    42	    const params = request.method === "GET" ? url.searchParams : await readOAuthBody(request);
    43	    const scopes = params.get("scope")?.split(/\s+/) ?? [];
    44	    if (scopes.includes("api:read") && !params.getAll("resource").some(Boolean)) {
    45	      return invalidResourceResponse();
    46	    }
    47	    return;
    48	  }
    49	
    50	  const body = await readOAuthBody(request);
    51	  if (body.get("grant_type") === "client_credentials" && !body.getAll("resource").some(Boolean)) {
    52	    return invalidResourceResponse();
    53	  }
    54	}
    55	
    56	async function readOAuthBody(request: Request) {
    57	  const contentType = request.headers.get("content-type") ?? "";
    58	  if (contentType.includes("application/x-www-form-urlencoded")) {
    59	    return new URLSearchParams(await request.clone().text());
    60	  }
    61	
    62	  if (contentType.includes("application/json")) {
    63	    const body = (await request
    64	      .clone()
    65	      .json()
    66	      .catch(() => null)) as Record<string, unknown> | null;
    67	    const params = new URLSearchParams();
    68	    if (typeof body?.grant_type === "string") params.set("grant_type", body.grant_type);
    69	    if (typeof body?.scope === "string") params.set("scope", body.scope);
    70	    if (typeof body?.resource === "string") params.append("resource", body.resource);
    71	    if (Array.isArray(body?.resource)) {
    72	      for (const resource of body.resource) {
    73	        if (typeof resource === "string") params.append("resource", resource);
    74	      }
    75	    }
    76	    return params;
    77	  }
    78	
    79	  return new URLSearchParams();
    80	}
    81	
    82	function invalidResourceResponse() {
    83	  return new Response(
    84	    JSON.stringify({
    85	      error: "invalid_target",
    86	      error_description: "The api:read scope requires a resource indicator.",
    87	    }),
    88	    { headers: { "content-type": "application/json" }, status: 400 },
    89	  );
    90	}
