     1	type SearchValue = string | string[];
     2	
     3	/**
     4	 * Keep top-level search parameters URLSearchParams-compatible.
     5	 *
     6	 * OAuth redirects can contain repeated, signed parameters. Treating those
     7	 * values as JSON arrays changes the signed query and makes it unverifiable.
     8	 */
     9	export function parseRouterSearch(searchString: string): Record<string, SearchValue> {
    10	  const search: Record<string, SearchValue> = Object.create(null);
    11	
    12	  for (const [key, value] of new URLSearchParams(searchString)) {
    13	    const current = search[key];
    14	    if (current === undefined) {
    15	      search[key] = value;
    16	    } else if (Array.isArray(current)) {
    17	      current.push(value);
    18	    } else {
    19	      search[key] = [current, value];
    20	    }
    21	  }
    22	
    23	  return search;
    24	}
    25	
    26	export function stringifyRouterSearch(search: Record<string, unknown>): string {
    27	  const params = new URLSearchParams();
    28	
    29	  for (const [key, value] of Object.entries(search)) {
    30	    if (value === undefined) continue;
    31	
    32	    if (Array.isArray(value)) {
    33	      for (const item of value) params.append(key, stringifySearchValue(item));
    34	    } else {
    35	      params.set(key, stringifySearchValue(value));
    36	    }
    37	  }
    38	
    39	  const query = params.toString();
    40	  return query ? `?${query}` : "";
    41	}
    42	
    43	function stringifySearchValue(value: unknown): string {
    44	  if (typeof value === "string") return value;
    45	  if (value !== null && typeof value === "object") return JSON.stringify(value);
    46	  return String(value);
    47	}
