    60	async function sha256Base64Url(value: string) {
    61	  const digest = new Uint8Array(
    62	    await crypto.subtle.digest("SHA-256", new TextEncoder().encode(value)),
    63	  );
    64	  let binary = "";
    65	  for (const byte of digest) binary += String.fromCharCode(byte);
    66	
    67	  return btoa(binary).replaceAll("+", "-").replaceAll("/", "_").replace(/=+$/, "");
    68	}
