   235	async function authorizeWithPkce(
   236	  clientId: string,
   237	  cookie: string,
   238	  targetResource = resourceIdentifier,
   239	  scope = "openid profile email",
   240	) {
   241	  const verifier = `verifier-${crypto.randomUUID()}-${crypto.randomUUID()}`;
   242	  const challenge = await sha256Base64Url(verifier);
   243	  const state = crypto.randomUUID();
   244	  const redirectUri = `${origin}/oauth/callback`;
   245	  const params = new URLSearchParams({
   246	    client_id: clientId,
   247	    code_challenge: challenge,
   248	    code_challenge_method: "S256",
   249	    redirect_uri: redirectUri,
   250	    response_type: "code",
   251	    resource: targetResource,
   252	    scope,
   253	    state,
   254	  });
   255	  const response = await SELF.fetch(`${origin}/api/auth/oauth2/authorize?${params}`, {
   256	    headers: { cookie },
   257	    redirect: "manual",
   258	  });
   259	  const location = response.headers.get("location");
   260	
   261	  expect(response.status).toBe(302);
   262	  expect(location).toBeTruthy();
   263	
   264	  const callback = new URL(location ?? redirectUri);
   265	  expect(callback.origin).toBe(origin);
   266	  expect(callback.searchParams.get("state")).toBe(state);
   267	  expect(callback.searchParams.get("code")).toBeTruthy();
   268	
   269	  return {
   270	    code: callback.searchParams.get("code") ?? "",
   271	    redirectUri,
   272	    verifier,
   273	  };
   274	}
