          eq(teamApplicationAssignments.applicationId, client.applicationId),
          eq(teamApplicationAssignments.status, "active"),
        ),
      )
      .where(
        and(
          eq(teamMemberships.userPrincipalId, principal.principalId),
          eq(teams.status, "active"),
        ),
      )
      .get(),
  ]);

  if (directAssignment) {
    return {
      ...baseDecision,
      assignmentSource: "direct",
      authorized: true,
      reason: "assigned",
    };
  }

  if (teamAssignment) {
    return {
      ...baseDecision,
      assignmentSource: "team",
      authorized: true,
      reason: "assigned",
    };
  }

  return {
    ...baseDecision,
    authorized: false,
    reason: "not_assigned",
  };
}

async function readConsentRequest(): Promise<ConsentRequest | null> {
  const state = await getOAuthProviderState();
  if (!state?.query) return null;

  const query = new URLSearchParams(state.query);
  const clientId = query.get("client_id");
  if (!clientId) return null;

  return {
    clientId,
    resources: query.getAll("resource"),
  };
