function readDeniedMessage(decision: ConsentAccessDecision, applicationLabel: string) {
  switch (decision.reason) {
    case "not_assigned":
      return `Your account is not assigned to ${applicationLabel}. Ask an administrator to grant you access before trying again.`;
    case "principal_disabled":
      return "Your Shui account is not active. Contact an administrator for help.";
    case "resource_mismatch":
      return "This authorization request targets a different Application resource.";
    case "client_disabled":
    case "application_disabled":
      return "This application is currently unavailable. Contact the application administrator.";
    default:
      return "Your account is not currently allowed to authorize this application.";
  }
}

function readClaimNames(value: string | undefined) {
  if (!value) return [];
  try {
    const parsed = JSON.parse(value) as Record<string, unknown>;
    return Object.entries(parsed).flatMap(([target, targetClaims]) =>
      targetClaims && typeof targetClaims === "object"
        ? Object.keys(targetClaims).map((claim) => `${target}.${claim}`)
        : [],
    );
  } catch {
    return [];
  }
}
export type ConsentAccessDecision = {
  application?: {
    id: string;
    name: string;
    resourceIdentifier: string;
  };
  assignmentSource?: "direct" | "team";
  authorized: boolean;
  clientId: string;
  managed: boolean;
  reason?:
    | "assigned"
    | "client_disabled"
    | "application_disabled"
    | "principal_disabled"
    | "not_assigned"
    | "resource_mismatch";
};

export async function preflightConsent(search: string): Promise<ConsentAccessDecision> {
  const response = await fetch("/api/auth/oauth2/consent/preflight", {
    body: JSON.stringify({ oauth_query: buildSignedOAuthQuery(search) }),
    credentials: "same-origin",
    headers: { "content-type": "application/json" },
    method: "POST",
  });
  const payload = (await response.json().catch(() => undefined)) as unknown;

  if (!response.ok) {
    throw new Error(readErrorMessage(payload) ?? "We could not verify access to this application.");
  }

  return payload as ConsentAccessDecision;
}

function buildSignedOAuthQuery(search: string) {
  const params = new URLSearchParams(search);
  if (!params.has("sig")) return undefined;

  const signedNames = new Set(params.getAll("ba_param"));
  if (signedNames.size === 0) return undefined;

  const signed = new URLSearchParams();
  for (const [key, value] of params) {
    if (key === "sig" || key === "ba_param" || signedNames.has(key)) signed.append(key, value);
  }

  return signed.toString();
}

function readErrorMessage(value: unknown) {
  if (!value || typeof value !== "object") return undefined;
  const record = value as Record<string, unknown>;
  if (typeof record.error_description === "string") return record.error_description;
  if (typeof record.message === "string") return record.message;
  return undefined;
}

