async function readApplicationClient(database: AppDb, applicationId: string, clientId: string) {
  const row = await database
    .select({
      applicationId: applicationOauthClients.applicationId,
      clientId: oauthClient.clientId,
      clientType: applicationOauthClients.clientType,
      name: oauthClient.name,
      redirectUris: oauthClient.redirectUris,
      scopes: oauthClient.scopes,
      disabled: oauthClient.disabled,
      createdAt: oauthClient.createdAt,
      updatedAt: oauthClient.updatedAt,
    })
    .from(applicationOauthClients)
    .innerJoin(oauthClient, eq(oauthClient.clientId, applicationOauthClients.clientId))
    .where(
      and(
        eq(applicationOauthClients.applicationId, applicationId),
        eq(applicationOauthClients.clientId, clientId),
      ),
    )
    .get();
  if (!row) throw new ApiError(404);
  const applicationResource = await database
    .select({ resourceIdentifier: applicationResources.resourceIdentifier })
    .from(applicationResources)
    .where(eq(applicationResources.applicationId, applicationId))
    .get();
  const linkedResources = await database
    .select({ resourceId: oauthClientResource.resourceId })
    .from(oauthClientResource)
    .where(eq(oauthClientResource.clientId, clientId))
    .all();
  if (
    !applicationResource ||
    linkedResources.length !== 1 ||
    linkedResources[0]?.resourceId !== applicationResource.resourceIdentifier
  ) {
    throw new ApiError(409);
  }
  return {
    applicationId: row.applicationId,
    clientId: row.clientId,
    clientType: row.clientType,
    name: row.name ?? row.clientId,
    redirectUris: parseStringArray(row.redirectUris),
    scopes: parseStringArray(row.scopes),

  const authorization = await authorizeWithPkce(clientId, user.cookie);
  const responses = await Promise.all([
    exchangeAuthorizationCode(clientId, authorization),
    exchangeAuthorizationCode(clientId, authorization),
  ]);
  const bodies = await Promise.all(responses.map((response) => response.json()));
  const successful = responses.filter((response) => response.status === 200);
  const rejected = bodies.filter(
    (body) => typeof body === "object" && body !== null && "error" in body,
  );

  expect(successful).toHaveLength(1);
  expect(rejected).toHaveLength(1);
  expect(rejected[0]).toMatchObject({ error: "invalid_grant" });
});

